//! Benchmark: parses `test/out/bench/bench.tmx` (generated by `test/benchmark.gd`) through the
//! [`Loader`] and emits the `tile_map_data` blob of each of its six tile layers, sequentially
//! and with one thread per layer. Files are read into memory first (the Godot side reads them
//! on the main thread); the times cover the loader (parse of the map, tilesets and template),
//! the gid table and the blobs.
//!
//! `cargo run --release --example bench [-- <map.tmx> [repetitions]]`

use std::collections::HashMap;
use std::time::Instant;
use tiled_core::cells::{layer_blobs, layer_blobs_parallel, BlobOptions, CellResolver};
use tiled_core::{Loader, Map};

fn load(path: &str, files: &HashMap<String, Vec<u8>>) -> Map {
    Loader::new(path, None)
        .run(|p| files.get(p).cloned())
        .expect("bench map loads")
}

fn main() {
    let args: Vec<String> = std::env::args().collect();
    let default = concat!(
        env!("CARGO_MANIFEST_DIR"),
        "/../../test/out/bench/bench.tmx"
    );
    let path = tiled_core::path::cleanup(args.get(1).map(String::as_str).unwrap_or(default));
    let reps: usize = args.get(2).and_then(|s| s.parse().ok()).unwrap_or(20);

    // Read every file the loader asks for once, outside the timing.
    let mut files = HashMap::new();
    let map = Loader::new(&path, None)
        .run(|p| {
            let b = std::fs::read(p).ok()?;
            files.insert(p.to_string(), b.clone());
            Some(b)
        })
        .unwrap_or_else(|e| panic!("{path}: {e:?} (generate it with test/benchmark.gd)"));
    let bytes: usize = files.values().map(Vec::len).sum();
    let objects: usize = map
        .all_layers()
        .iter()
        .map(|l| l.objects.as_ref().map_or(0, Vec::len))
        .sum();

    let opts = BlobOptions::default();
    let ms = |a: Instant, b: Instant| (b - a).as_secs_f64() * 1000.0;
    let (mut parse, mut seq, mut par) = (Vec::new(), Vec::new(), Vec::new());
    let mut cells = 0;
    for _ in 0..reps {
        // Sequential: load, then every layer's blob on this thread.
        let t0 = Instant::now();
        let map = load(&path, &files);
        let t1 = Instant::now();
        let lookup = CellResolver::new(&map).lookup();
        let blobs = layer_blobs(&map, &lookup, opts);
        let t2 = Instant::now();
        cells = blobs
            .iter()
            .map(|(_, b)| (b.as_ref().unwrap().len() - 2) / 12)
            .sum();
        std::hint::black_box(&blobs);
        drop(blobs);
        drop(map);

        // Threaded: load, then one thread per layer.
        let t3 = Instant::now();
        let map = load(&path, &files);
        let lookup = CellResolver::new(&map).lookup();
        let blobs = layer_blobs_parallel(&map, &lookup, opts);
        let t4 = Instant::now();
        std::hint::black_box(&blobs);
        parse.push(ms(t0, t1));
        seq.push(ms(t0, t2));
        par.push(ms(t3, t4));
    }
    let stats = |v: &mut Vec<f64>| {
        v.sort_by(|a, b| a.partial_cmp(b).unwrap());
        (v[0], v[v.len() / 2])
    };
    let (pmin, pmed) = stats(&mut parse);
    let (smin, smed) = stats(&mut seq);
    let (tmin, tmed) = stats(&mut par);
    println!(
        "bench: {} files, {} KB, {} tile layers, {cells} cells, {objects} objects, {reps} runs",
        files.len(),
        bytes / 1024,
        map.all_layers()
            .iter()
            .filter(|l| l.kind_or_tile() == "tilelayer")
            .count(),
    );
    println!(
        "  loader (parse map + tilesets + template)   min {pmin:6.2} ms  median {pmed:6.2} ms"
    );
    println!(
        "  load + 6 blobs, sequential                 min {smin:6.2} ms  median {smed:6.2} ms"
    );
    println!(
        "  load + 6 blobs, one thread per layer       min {tmin:6.2} ms  median {tmed:6.2} ms"
    );
    println!(
        "RESULT threaded_median_ms={tmed:.2} sequential_median_ms={smed:.2} gate=15ms {}",
        if tmed < 15.0 { "PASS" } else { "FAIL" }
    );
}
